const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const userPrompt = $input.first().json.chatInput || "general-task";

const shortName = userPrompt
  .toLowerCase()
  .replace(/[^a-z0-9\s]/g, '')
  .trim()
  .split(/\s+/)
  .slice(0, 3)
  .join('-');

return [
  {
    json: {
      task_id: `${dateStr}-${shortName || 'assignment'}`,
      current_time_ist: now.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }),
      user_request: userPrompt,
      session_id: $input.first().json.sessionId || 'default-session'
    }
  }
];
